import { assertReaderModelAcknowledgement, requiredDefinitionReaderModel, resourceAliasesToMap, } from '@sanity/workflow-engine';
import { fail } from './fail.js';
import { canPromptOnStderr, selectOnStderr } from './prompt.js';
export function deploymentLabel({ name, partition, }) {
    return `${name} (${partition})`;
}
export async function selectDeployment(config, { name, partition, orAlternative = '', interactive, chooseName = chooseDeploymentName, }) {
    if (name !== undefined) {
        const deployment = config.deployments.find((candidate) => candidate.name === name);
        if (deployment === undefined) {
            fail(`No deployment named "${name}".`, availableDeployments(config));
        }
        return deployment;
    }
    if (partition !== undefined) {
        const matches = deploymentsForPartition(config, partition);
        const [sole, ...rest] = matches;
        if (sole === undefined || rest.length > 0) {
            fail(`Multiple deployments in partition "${partition}" — pass --deployment to choose one.`, availableDeployments(config, matches));
        }
        return sole;
    }
    return selectDefaultDeployment(config, { orAlternative, interactive, chooseName });
}
async function selectDefaultDeployment(config, { orAlternative, interactive, chooseName, }) {
    if (config.deployments.length > 1) {
        if (interactive ?? canPromptOnStderr()) {
            const selectedName = await chooseName(config.deployments);
            return selectDeployment(config, { name: selectedName, partition: undefined });
        }
        fail(`Multiple deployments configured — pass --deployment or --partition${orAlternative}.`, availableDeployments(config));
    }
    const [sole] = config.deployments;
    if (sole === undefined) {
        fail('No deployments configured.');
    }
    return sole;
}
export function deploymentsForPartition(config, partition) {
    const matches = config.deployments.filter((candidate) => candidate.partition === partition);
    if (matches.length === 0) {
        fail(`No deployment for partition "${partition}".`, availableDeployments(config));
    }
    return matches;
}
export async function selectDeployments(config, { name, partition, allPartitions, interactive, chooseName }) {
    if (allPartitions) {
        return config.deployments;
    }
    if (partition !== undefined) {
        return deploymentsForPartition(config, partition);
    }
    return [
        await selectDeployment(config, {
            name,
            partition,
            orAlternative: ', or --all-partitions to deploy every deployment',
            interactive,
            chooseName,
        }),
    ];
}
async function chooseDeploymentName(deployments) {
    return selectOnStderr({
        message: 'Select a deployment',
        choices: deployments.map(({ name, partition }) => ({
            name,
            value: name,
            description: `partition: ${partition}`,
        })),
    });
}
function availableDeployments(config, deployments = config.deployments) {
    return `Available deployments: ${deployments.map(deploymentLabel).join(', ')}`;
}
export function acknowledgeDeployment(deployment, definitions) {
    const expectedMinReaderModel = deployment.expectedMinReaderModel;
    assertReaderModelAcknowledgement(expectedMinReaderModel, {
        context: `Deployment ${deployment.name}`,
        requiredMinReaderModel: requiredDefinitionReaderModel(definitions),
    });
    return { ...deployment, expectedMinReaderModel };
}
export function deploymentToTarget(deployment) {
    return {
        expectedMinReaderModel: deployment.expectedMinReaderModel,
        partition: deployment.partition,
        workflowResource: deployment.workflowResource,
        resourceAliases: resourceAliasesToMap(deployment.resourceAliases),
    };
}
